use burn::backend::NdArray;
use burn::tensor::{Device, Distribution, Tensor};

fn dev() -> Device {
    Device::ndarray()
}

/// Mean of squares: NaN or Inf in any element shows up in the scalar, and
/// `into_scalar` is stable across the burn versions this workspace has seen.
fn finite(t: &Tensor<3>) -> bool {
    let mean_sq: f32 = t.clone().powf_scalar(2.0).mean().into_scalar();
    mean_sq.is_finite()
}

/// The example from `INTEGRATION.md`, run for real: a gated delta net builds
/// and produces finite output on the plain tensor path.
#[test]
fn hello_gated_delta_net() {
    let x = Tensor::<3>::random([1, 16, 128], Distribution::Default, &dev());

    let layer = burn_fused::burn_kda::KdaModule::new(&Default::default(), 0.0, &dev());
    let y = layer.forward_train::<NdArray>(x);

    assert_eq!(y.dims(), [1, 16, 128]);
    assert!(finite(&y), "KDA tensor path produced a non-finite value");
}

/// The attention set: the mixer and positional crates a user composes into an
/// attention block, each taken through the facade by one path. This is the
/// combination `INTEGRATION.md` tells people to start from.
#[test]
fn attention_arms_compose() {
    let (b, t, d) = (1, 8, 64usize);

    // GDN-2, the gated delta rule KDA specialises.
    let gdn_cfg = burn_fused::burn_gdn2::Gdn2Config {
        hidden_size: d,
        num_heads: 2,
        head_dim: 32,
        chunk_size: 16,
        ..Default::default()
    };
    let gdn = burn_fused::burn_gdn2::GatedDeltaNet2::new(&gdn_cfg, &dev());
    let y = gdn.forward_train::<NdArray>(Tensor::<3>::random(
        [b, t, d],
        Distribution::Default,
        &dev(),
    ));
    assert_eq!(y.dims(), [b, t, d]);
    assert!(finite(&y), "GDN-2 tensor path produced a non-finite value");

    // RoPE: the frequency table and the rotate, both through the facade.
    let (cos, sin) = burn_fused::burn_rope::precompute_freqs(32, t, 10_000.0, &dev());
    let x = Tensor::<4>::random([b, t, 2, 32], Distribution::Default, &dev());
    let rotated = burn_fused::burn_rope::apply_rope_4d::<NdArray>(x, cos, sin);
    assert_eq!(rotated.dims(), [b, t, 2, 32]);

    // NoPE (`burn-nope`) used to be exercised here. It was deleted 2026-09-28
    // as unreachable from `crates/dormouse-*` with no reason to stay — see
    // `docs/library-crate-fate.md` in the dormouse repository. Worth recording
    // that this test was the only thing making it look alive.
}

/// The doc's dtype claim, on the path a CPU user actually gets: the tensor
/// fallback is correct and finite. A fused kernel that reads a non-f32 buffer
/// as f32 is the failure this guards against (see INTEGRATION.md).
#[test]
fn tensor_fallback_is_finite_for_the_norm_and_the_gate() {
    let (b, t, d) = (1, 4, 64usize);

    let normed = burn_fused::burn_rmsnorm::RMSNorm::new(d, 1e-5, &dev()).forward(
        Tensor::<3>::random([b, t, d], Distribution::Default, &dev()),
    );
    assert!(finite(&normed), "RMSNorm tensor path is not finite");

    let gated = burn_fused::burn_swiglu::swiglu_gate(Tensor::<3>::random(
        [b, t, 2 * d],
        Distribution::Default,
        &dev(),
    ));
    assert_eq!(gated.dims(), [b, t, d]);
    assert!(finite(&gated), "SwiGLU tensor path is not finite");
}

/// `lib.rs`, the facade feature list and the `use` list above are generated. If
/// this fails, run `tools/gen_facade.py` and commit the result.
#[test]
fn generated_facade_is_up_to_date() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("the facade lives inside the fork");
    let out = std::process::Command::new("python3")
        .arg(root.join("tools/gen_facade.py"))
        .arg("--check")
        .current_dir(root)
        .output()
        .expect("python3 is required to check the generated facade");
    assert!(
        out.status.success(),
        "tools/gen_facade.py --check failed:\n{}",
        String::from_utf8_lossy(&out.stderr)
    );
}
